"""One existing own-master ROI →256 transparent UI portrait, never new AI artwork."""
from PIL import Image
import pathlib,json,hashlib,sys,datetime
base=pathlib.Path(__file__).resolve().parent;root=base.parents[2]
definitions={
 'cloud-tortoise-warden':{'sourceRoleId':11,'name':'玄龟','roi':[380,60,980,560],'why':'Complete charcoal hair/turtle clasp and ribbons, warm broad face and short collar. Upper-head alpha8 extent startsx386, so left380 preserves hair and excludes the bamboo clapper edge; original raised tally remains naturally at lower-right crop edge, never moved.'},
 'pine-cloud-elder':{'sourceRoleId':13,'name':'松翁','roi':[380,65,920,749],'why':'Complete white bun/pine pin, eyebrows/face/side hair and long beard with a little collar; left380 excludes most cane, narrow portrait preserves full beard rather than crop it to enlarge eyes. Any natural hand/whisk edge remaining is not relocated.'},
 'jade-craft-artisan':{'sourceRoleId':14,'name':'玉匠','roi':[320,45,1004,654],'why':'Complete bob, both short braids and left cloud clip/beads, freckled face and collar. Neighbouring mallet/cloud fragments remain at natural source-edge positions; no component erase or reposition.'},
 'paper-kite-wanderer':{'sourceRoleId':15,'name':'纸鸢','roi':[160,42,1224,798],'why':'Complete wide bamboo hat/cloud pin/ribbons, both braids and face plus shoulder collar. Wide hat requires smaller face within256; no hat clipping or separate face zoom.'},
 'cinnabar-seal-keeper':{'sourceRoleId':16,'name':'赤砂','roi':[270,0,954,570],'why':'Complete short auburn curls/jade headband/seal pin and dangling ornaments, adult almond eyes/freckles and collar. Source top is included from0 because the original hair clearance is tight; no hair reconstruction.'}
}
id=sys.argv[1];assert id in definitions;d=definitions[id]
mapping_path=root/'assets/characters/motion-generated/roster-skin-mapping-20261028.json';mapping=json.loads(mapping_path.read_text(encoding='utf-8'));slot=next(s for s in mapping['slots']if s['sourceRoleId']==d['sourceRoleId']);assert slot['appearance']['identityId']==id
master=root.joinpath(*pathlib.PurePosixPath(slot['appearance']['master']).parts);raw=master.read_bytes();generation_path=pathlib.Path(str(master)+'.generation.json');gen=json.loads(generation_path.read_text(encoding='utf-8'));sha=hashlib.sha256(raw).hexdigest();assert sha==gen['sha256']
im=Image.open(master).convert('RGBA');assert im.size==(1254,1254)
l,t,r,b=d['roi'];assert 0<=l<r<=im.width and 0<=t<b<=im.height
crop=im.crop((l,t,r,b));w,h=crop.size;s=228/max(w,h);rw=round(w*s);rh=round(h*s)
# Chosen ROI dimensions yield equal exact x/y scale after integer rasterization.
assert abs(rw/w-rh/h)<1e-12
resized=crop.convert('RGBa').resize((rw,rh),Image.Resampling.LANCZOS).convert('RGBA');placement=[(256-rw)//2,(256-rh)//2]
portrait=Image.new('RGBA',(256,256),(0,0,0,0));portrait.paste(resized,tuple(placement));dest=base/(id+'-256.png');portrait.save(dest)
a=portrait.getchannel('A');m=a.point(lambda v:255 if v>=8 else 0);bb=m.getbbox();edge={'left':sum(a.getpixel((0,y))>=8 for y in range(256)),'right':sum(a.getpixel((255,y))>=8 for y in range(256)),'top':sum(a.getpixel((x,0))>=8 for x in range(256)),'bottom':sum(a.getpixel((x,255))>=8 for x in range(256))}
source_a=im.getchannel('A');source_edge={'left':sum(source_a.getpixel((0,y))>=8 for y in range(im.height)),'right':sum(source_a.getpixel((im.width-1,y))>=8 for y in range(im.height)),'top':sum(source_a.getpixel((x,0))>=8 for x in range(im.width)),'bottom':sum(source_a.getpixel((x,im.height-1))>=8 for x in range(im.width))}
qa=base/'qa';qa.mkdir(exist_ok=True);ivory=Image.new('RGBA',(256,256),(246,240,222,255));ivory.alpha_composite(portrait);preview=qa/(id+'-256-ivory.png');ivory.convert('RGB').save(preview)
record={'schemaVersion':1,'file':'assets/characters/portraits-candidates/'+dest.name,'sha256':hashlib.sha256(dest.read_bytes()).hexdigest(),'createdAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'sourceRoleId':d['sourceRoleId'],'identityId':id,'name':d['name'],'type':'derived_ui_portrait_candidate_not_new_character_or_new_generation','mappingRecord':'assets/characters/motion-generated/roster-skin-mapping-20261028.json','source':{'file':slot['appearance']['master'],'sha256':sha,'actualSourceCanvas':list(im.size),'sourceGenerationRecord':slot['appearance']['master']+'.generation.json','nativeGenerationSizeFromRecord':[gen['width'],gen['height']],'actualModel':gen.get('actualModel'),'actualQuality':gen.get('actualQuality'),'generationTime':gen.get('generatedAt'),'sourceAlpha8OuterEdges':source_edge},'operation':{'kind':'one manual rectangular whole ROI crop then uniform premultiplied-alpha LANCZOS shrink and centered transparent placement','sourceCropLTRB':d['roi'],'sourceCropSize':[w,h],'uniformScale':s,'resampledCropSize':[rw,rh],'placementXY':placement,'outputCanvas':[256,256],'requestedTransparentInset':14,'selectionReason':d['why'],'sourceMasterActuallyViewed':True,'noComponentMovement':True,'noFaceOrHatSeparateScale':True,'noMirroring':True,'newImageGeneration':False},'output':{'alphaExtrema':a.getextrema(),'alpha8BBoxLTRB':bb,'alpha8MarginsLTRB':[bb[0],bb[1],256-bb[2],256-bb[3]],'alpha8OuterEdges':edge,'preview':'assets/characters/portraits-candidates/qa/'+preview.name,'actual256Viewed':False},'runtimeAdopted':False,'clientApproved':False,'status':'portrait_candidate_pending_actual256_visual_review'}
dest.with_suffix('.png.source.json').write_text(json.dumps(record,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
preview.with_suffix('.png.source.json').write_text(json.dumps({'derivedFrom':{'file':record['file'],'sha256':record['sha256'],'sourceRecord':record['file']+'.source.json'},'operation':'256px ivory compositing for necessary individual visual QA only; no resizing or new generation.'},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps({'file':record['file'],'sourceRoleId':d['sourceRoleId'],'sourceCrop':d['roi'],'scale':s,'placement':placement,'alpha8Margins':record['output']['alpha8MarginsLTRB'],'sourceOuter':source_edge,'runtimeAdopted':False},ensure_ascii=False))
